// src/pages/Home.jsx
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom"; // 引入 Hook
import { useUI } from "../context/UIContext";
import Hero from "../components/layout/Hero";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";

const Home = () => {
  const navigate = useNavigate(); // 初始化導航功能
  const { setHeroData, setAllAnswers } = useUI();
  const [formData, setFormData] = useState({
    userName: "",
    birthday: "",
  });

  useEffect(() => {
    setHeroData({
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: "您好，我是乳房外科小幫手",
      description: "請填寫基本資料，再按下開始。",
    });
  }, [setHeroData]);

  // 建立跳轉處理函式
  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));

    // 跳轉到 selection 頁面，並選擇性傳遞資料
    navigate("/selection");
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className={styles.homeContainer}>
      <div className={styles.inputWrapper}>
        <Input
          label="請輸入您的姓名"
          name="userName"
          placeholder="請輸入您的姓名"
          value={formData.userName}
          onChange={handleInputChange}
        />

        <Input
          label="請輸入您的出生年月日"
          type="date"
          name="birthday"
          value={formData.birthday}
          onChange={handleInputChange}
        />
      </div>
      <div className={styles.buttonWrapper}>
        <Button onClick={handleStart} fullWidth>
          開始
        </Button>
      </div>
    </div>
  );
};

export default Home;
